<?php require_once __DIR__.'/../config/config.php';admin_required();$statuses=['New Order','Confirmed','Processing','Shipped','Delivered','Cancelled'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$status=$_POST['status'];if(in_array($status,$statuses,true)){$pdo->beginTransaction();$s=$pdo->prepare('SELECT status FROM orders WHERE id=? FOR UPDATE');$s->execute([$id]);$old=$s->fetchColumn();$pdo->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$status,$id]);$pdo->prepare('INSERT INTO order_status_history(order_id,status,note) VALUES(?,?,?)')->execute([$id,$status,'Status updated by admin']);if($status==='Cancelled'&&$old!=='Cancelled'){$q=$pdo->prepare('SELECT product_id,quantity FROM order_items WHERE order_id=?');$q->execute([$id]);foreach($q as $it)if($it['product_id'])$pdo->prepare('UPDATE products SET stock=stock+? WHERE id=?')->execute([$it['quantity'],$it['product_id']]);}$pdo->commit();}}$orders=$pdo->query('SELECT o.*,c.name,c.phone FROM orders o JOIN customers c ON c.id=o.customer_id ORDER BY o.created_at DESC')->fetchAll();require 'layout.php';?><h1>Orders</h1><div class="table-responsive"><table class="table"><tr><th>Order</th><th>Customer</th><th>Phone</th><th>Total</th><th>Status</th><th>Update</th></tr><?php foreach($orders as $o):?><tr><td><?=e($o['order_code'])?></td><td><?=e($o['name'])?></td><td><?=e($o['phone'])?></td><td><?=money($o['total'])?></td><td><?=e($o['status'])?></td><td><form method="post" class="d-flex gap-1"><?=csrf_field()?><input type="hidden" name="id" value="<?=$o['id']?>"><select class="form-select form-select-sm" name="status"><?php foreach($statuses as $st):?><option <?=$st===$o['status']?'selected':''?>><?=$st?></option><?php endforeach;?></select><button class="btn btn-sm btn-gold">Save</button></form></td></tr><?php endforeach;?></table></div><?php require 'end.php';?>